-- ===== calls table (docs/sql/calls.sql) =====
-- The voice agent's call log (P1). Run once in Supabase → SQL Editor, after
-- docs/SUPABASE_SETUP.md §1–2 (it references public.addresses).
--
-- One row per phone call, keyed by Retell's call_id. The telephony server upserts it with the
-- service-role key as the call progresses; routing only ever moves up within a call.
-- Columns follow docs/DATA_CONTRACT.md §2 plus what the board's queue shows.

create table if not exists public.calls (
  id                 uuid primary key default gen_random_uuid(),
  call_id            text not null unique,
  mode               text check (mode in ('wildfire', 'routine')),
  address            text,                -- as the caller said it
  address_id         uuid references public.addresses(id) on delete set null,
  subject_name       text,
  from_number        text,                -- callback number
  with_them_now      boolean not null default false,
  emergency          boolean not null default false,
  caller_update      text,                -- newer info from the caller than the record
  last_contact_hours numeric,
  vulnerability      jsonb not null default '{}'::jsonb,
  red_flags          jsonb not null default '{}'::jsonb,
  caller_state       text check (caller_state in ('calm', 'worried', 'distressed', 'panicked')),
  prior_callers      int not null default 0,  -- other numbers that already called about this address
  routing            text not null check (routing in (
                       'human_now', 'priority_queue', 'answered_by_agent', 'scheduled_followup',
                       'abandoned_callback',   -- hung up before routing: call back
                       'callback_queue')),     -- transfer didn't connect: call back first
  severity           int check (severity between 1 and 5),
  reason             text,                -- one line for the board
  simulated          boolean not null default false,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz
);

create index if not exists calls_newest on public.calls (created_at desc);

-- Same rule as the other tables: anon reads nothing; the board reads with its minted token;
-- only the telephony server writes (service role bypasses RLS).
alter table public.calls enable row level security;

drop policy if exists "signed-in portals can read calls" on public.calls;
create policy "signed-in portals can read calls"
  on public.calls for select to authenticated using (true);

-- Live queue on the board.
alter publication supabase_realtime add table public.calls;

-- Reset between demo runs:
--   delete from public.calls;

-- ===== docs/sql/calls_retell.sql =====
-- Retell call data on public.calls (P1). Run once in Supabase → SQL Editor, after calls.sql.
-- Safe to run twice. Makes `calls` the complete live record of every phone call, so the board
-- can read everything from Supabase (Realtime is already on for this table) instead of the
-- telephony server's /events feed.
--
-- Row lifecycle (docs/DATA_CONTRACT.md §6):
--   call starts      → status 'in_progress', routing null
--   lookup_address   → address, subject_name, lookup_*, inside_perimeter
--   during the call  → caller_state, distress_score, bypass, transcript (every few seconds)
--   log_call         → routing, severity, reason   (routing only ever moves up)
--   transfer         → transfer_status
--   call ends        → status 'ended', ended_at, duration_s, disconnection_reason, transcript
--   Retell analysis  → summary, user_sentiment, recording_url, latency_ms (~seconds later)

-- A call in progress hasn't been routed yet.
alter table public.calls alter column routing drop not null;

alter table public.calls
  add column if not exists status               text not null default 'in_progress'
                                                 check (status in ('in_progress', 'ended')),
  add column if not exists direction            text,
  add column if not exists started_at           timestamptz,
  add column if not exists ended_at             timestamptz,
  add column if not exists duration_s           int,
  add column if not exists disconnection_reason text,            -- Retell's: user_hangup, call_transfer, …
  add column if not exists transfer_status      text check (transfer_status in ('ringing', 'connected', 'failed')),
  add column if not exists bypass               boolean not null default false,  -- emergency/distress detected live
  add column if not exists bypass_reason        text,
  add column if not exists distress_score       int not null default 0,          -- live word score; 3 = handoff threshold
  add column if not exists lookup_found         boolean,
  add column if not exists lookup_status        text,            -- null unless the caller named the resident
  add column if not exists name_match           boolean,
  add column if not exists inside_perimeter     boolean,
  add column if not exists report_written       text,            -- status written back to status_log, if any
  add column if not exists transcript           text,
  add column if not exists summary              text,            -- Retell post-call analysis
  add column if not exists user_sentiment       text,            -- Retell: Positive / Negative / Neutral / Unknown
  add column if not exists recording_url        text,
  add column if not exists latency_ms           int;             -- Retell end-to-end p50 for the call

-- Make PostgREST see the new columns immediately.
notify pgrst, 'reload schema';

-- ===== docs/sql/calls_map.sql =====
-- Map placement and decision record on public.calls (P1). Run once in Supabase → SQL Editor,
-- after calls.sql and calls_retell.sql. Safe to run twice.
--
--   lat, lng, geo_precision  where the call goes on the map. 'house' = the household's own point
--                            (address_id is set); 'street' = the centre of the known houses on the
--                            street the caller named, for a house not in our records; null = we
--                            can't place it.
--   decision_trace           the routing decision as data: the facts the router saw and every rule
--                            that decided, in order. Shape in docs/DATA_CONTRACT.md §7.

alter table public.calls
  add column if not exists lat            double precision,
  add column if not exists lng            double precision,
  add column if not exists geo_precision  text check (geo_precision in ('house', 'street')),
  add column if not exists decision_trace jsonb;

-- The map asks "which calls are about this house" on every selection.
create index if not exists calls_by_address on public.calls (address_id, created_at desc);

notify pgrst, 'reload schema';

-- ===== docs/sql/houses.sql =====
-- public.houses: the current state of every household, one row each (P1),
-- plus the dispatch dashboard: two columns on public.calls (reasoning, suggestions) and the
-- suggestion_decisions audit table.
-- Run once in Supabase → SQL Editor, after SUPABASE_SETUP.md §1–2 and the three calls*.sql files.
-- Safe to run twice.
--
-- Nobody writes the evacuation or call columns directly: triggers on status_log, calls and
-- addresses keep them true, so this table can't disagree with the log it summarises.
-- fire_threat_* come from research (docs/research/street-threat.json via
-- `npm run apply-threat`) and survive every refresh.

-- The dashboard's view of each call: the steps behind the routing (from decision_trace) and
-- suggested resources a dispatcher confirms. Shapes in docs/DATA_CONTRACT.md §8.
alter table public.calls
  add column if not exists reasoning   jsonb,
  add column if not exists suggestions jsonb;

-- A dispatcher's confirm/dismiss on a suggestion. Append-only: the audit trail of every human
-- decision on an automated suggestion. Kept out of calls.suggestions because the server
-- rewrites that column when a call is re-routed. The newest row per (call_id, suggestion_id) wins.
create table if not exists public.suggestion_decisions (
  id            uuid primary key default gen_random_uuid(),
  call_id       text not null references public.calls(call_id) on delete cascade,
  suggestion_id text not null,
  resource      text,                 -- the suggestion's wording at the time it was decided
  decision      text not null check (decision in ('confirmed', 'dismissed')),
  decided_by    text not null,        -- the signed-in role
  decided_at    timestamptz not null default now()
);
create index if not exists suggestion_decisions_by_call on public.suggestion_decisions (call_id, decided_at desc);
alter table public.suggestion_decisions enable row level security;
drop policy if exists "signed-in portals can read decisions" on public.suggestion_decisions;
create policy "signed-in portals can read decisions"
  on public.suggestion_decisions for select to authenticated using (true);
do $$ begin
  alter publication supabase_realtime add table public.suggestion_decisions;
exception when duplicate_object then null; end $$;

create table if not exists public.houses (
  id                        uuid primary key references public.addresses(id) on delete cascade,
  address                   text not null,
  zone_id                   text,
  -- Evacuation: the newest status_log row for this household.
  evacuation_status         public.status_kind not null default 'unknown',
  evacuation_status_source  public.status_source,
  evacuation_note           text,
  last_checked_at           timestamptz,          -- when that status was recorded (null = never checked)
  -- Fire threat for this house's street, from research. Null = not assessed.
  fire_threat_level         text check (fire_threat_level in ('extreme', 'high', 'moderate', 'low')),
  fire_threat_reason        text,
  fire_threat_source        text,
  -- Calls to the line about this household.
  called_about              boolean not null default false,
  call_count                int not null default 0,
  last_called_at            timestamptz,
  updated_at                timestamptz not null default now()
);

create index if not exists houses_by_zone on public.houses (zone_id);
create index if not exists houses_by_threat on public.houses (fire_threat_level, evacuation_status);

-- Recompute one household from the source tables. Leaves fire_threat_* alone.
create or replace function public.refresh_house(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  if p_id is null then return; end if;
     last_checked_at, called_about, call_count, last_called_at, updated_at)
  select a.id, a.address, a.zone_id,
         coalesce(s.status, 'unknown'), s.source, s.note, s.recorded_at,
         coalesce(c.n, 0) > 0, coalesce(c.n, 0), c.last_at, now()
  from public.addresses a
  left join lateral (
    select status, source, note, recorded_at from public.status_log
    where address_id = a.id order by recorded_at desc limit 1
  ) s on true
  left join lateral (
    select count(*)::int as n, max(created_at) as last_at from public.calls where address_id = a.id
  ) c on true
  where a.id = p_id
  on conflict (id) do update set
    address = excluded.address,
    zone_id = excluded.zone_id,
    evacuation_status = excluded.evacuation_status,
    evacuation_status_source = excluded.evacuation_status_source,
    evacuation_note = excluded.evacuation_note,
    last_checked_at = excluded.last_checked_at,
    called_about = excluded.called_about,
    call_count = excluded.call_count,
    last_called_at = excluded.last_called_at,
    updated_at = now();
end $$;

create or replace function public.houses_from_status() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  -- NEW doesn't exist on DELETE and OLD doesn't on INSERT, so branch on the operation.
  if tg_op in ('INSERT', 'UPDATE') then perform public.refresh_house(new.address_id); end if;
  if tg_op = 'DELETE' or (tg_op = 'UPDATE' and old.address_id is distinct from new.address_id) then
    perform public.refresh_house(old.address_id);
  end if;
  return null;
end $$;

create or replace function public.houses_from_calls() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op in ('INSERT', 'UPDATE') then perform public.refresh_house(new.address_id); end if;
  if tg_op = 'DELETE' or (tg_op = 'UPDATE' and old.address_id is distinct from new.address_id) then
    perform public.refresh_house(old.address_id);
  end if;
  return null;
end $$;

create or replace function public.houses_from_addresses() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  perform public.refresh_house(new.id);
  return null;
end $$;

drop trigger if exists houses_status on public.status_log;
create trigger houses_status after insert or update or delete on public.status_log
  for each row execute function public.houses_from_status();

-- Only when a call is linked to (or moved off) a household, not on every transcript update.
drop trigger if exists houses_calls on public.calls;
create trigger houses_calls after insert or update of address_id or delete on public.calls
  for each row execute function public.houses_from_calls();

drop trigger if exists houses_addresses on public.addresses;
create trigger houses_addresses after insert or update on public.addresses
  for each row execute function public.houses_from_addresses();

-- Backfill every household.
select public.refresh_house(id) from public.addresses;

-- Same rules as the other tables: anon reads nothing; the board reads with its minted token;
-- only the server and the triggers write.
alter table public.houses enable row level security;
drop policy if exists "signed-in portals can read houses" on public.houses;
create policy "signed-in portals can read houses"
  on public.houses for select to authenticated using (true);

do $$ begin
  alter publication supabase_realtime add table public.houses;
exception when duplicate_object then null; end $$;

notify pgrst, 'reload schema';

-- ===== docs/sql/house_colors.sql =====
-- House colours decided by Supabase, from the record AND the Retell calls about each house,
-- plus a house_events feed: "Retell registered 1515 Via de la Paz as RED". Run once in
-- Supabase -> SQL Editor, after houses.sql. Safe to run twice.
--
--   red    marked staying (refused), or a call about it needed a person now
--          (routing human_now / callback_queue, or emergency/distress heard live).
--          An officer's check that is NEWER than that call and found the house cleared or
--          self-evacuated closes the call out. A phone report, a resident reply, an unanswered
--          knock or an older check does not: the urgent call stands.
--   green  cleared or self-evacuated within the last 120 minutes
--   orange an officer knocked and got no answer
--   yellow reported leaving (evacuating), no follow-up yet
--   grey   no current verified record: never checked, or the last clear has gone stale.
--          This is every house until a real check is recorded.
--
-- Time recolours too: a clear stops being green (it goes grey) 120 minutes after it was
-- recorded. Nothing writes a row when that happens, so expire_house_colors() (below) does it
-- once a minute.

-- A house_events row is written when a RETELL call (a calls row, or a status_log row with
-- source 'call') either links a house for the first time or changes its colour. Officer taps
-- recolour houses too, but don't raise a Retell event.

alter table public.houses
  add column if not exists color            text not null default 'grey' check (color in ('green', 'yellow', 'orange', 'red', 'grey')),
  add column if not exists color_reason     text,
  add column if not exists color_changed_at timestamptz;

create table if not exists public.house_events (
  id             uuid primary key default gen_random_uuid(),
  house_id       uuid not null references public.houses(id) on delete cascade,
  address        text not null,
  color          text not null check (color in ('green', 'yellow', 'orange', 'red', 'grey')),
  previous_color text check (previous_color in ('green', 'yellow', 'orange', 'red', 'grey')),
  first_call     boolean not null default false,   -- the house's first call to the line
  reason         text,
  call_id        text,
  created_at     timestamptz not null default now()
);
create index if not exists house_events_newest on public.house_events (created_at desc);

-- A project that already ran an earlier version has narrower CHECKs and a yellow default.
-- Widen them (drop-and-add is safe to repeat) and make grey the default.
alter table public.houses alter column color set default 'grey';
alter table public.houses drop constraint if exists houses_color_check;
alter table public.houses add constraint houses_color_check check (color in ('green', 'yellow', 'orange', 'red', 'grey'));
alter table public.house_events drop constraint if exists house_events_color_check;
alter table public.house_events add constraint house_events_color_check check (color in ('green', 'yellow', 'orange', 'red', 'grey'));
alter table public.house_events drop constraint if exists house_events_previous_color_check;
alter table public.house_events add constraint house_events_previous_color_check
  check (previous_color in ('green', 'yellow', 'orange', 'red', 'grey'));

-- The colour rule, in one place.
create or replace function public.house_color(p_status public.status_kind, p_checked timestamptz, p_house uuid)
returns table (color text, reason text)
language sql stable set search_path = public as $$
  with urgent as (
    select c.routing, c.bypass, c.bypass_reason, c.reason
    from public.calls c
    where c.address_id = p_house
      and (c.routing in ('human_now', 'callback_queue') or c.bypass)
      -- closed out by a later officer check that reached a conclusion (see the rules above)
      and not coalesce(
        p_status in ('cleared', 'self_out')
        and p_checked > c.created_at
        and (select h.evacuation_status_source from public.houses h where h.id = p_house) = 'officer',
        false)
    order by c.created_at desc limit 1
  )
  select
    case
      when p_status = 'refused' then 'red'
      when exists (select 1 from urgent) then 'red'
      when p_status in ('cleared', 'self_out') and p_checked >= now() - interval '120 minutes' then 'green'
      when p_status = 'no_answer' then 'orange'
      when p_status = 'in_transit' then 'yellow'
      else 'grey'
    end,
    case
      when p_status = 'refused' then 'people at this house are staying'
      when exists (select 1 from urgent) then coalesce(
        (select case when routing = 'callback_queue' then 'a caller about this house needs a call back'
                     else 'a caller about this house needed a person now' end from urgent), 'urgent call')
      when p_status in ('cleared', 'self_out') and p_checked >= now() - interval '120 minutes'
        then case when p_status = 'self_out' then 'resident reported out' else 'checked and cleared' end
      when p_status in ('cleared', 'self_out') then 'last check is more than 2 hours old'
      when p_status = 'no_answer' then 'last knock got no answer'
      when p_status = 'in_transit' then 'reported leaving, no follow-up'
      else 'no verified record'
    end;
$$;

-- refresh_house now also recolours, and logs a Retell event when a call registers or changes
-- the house. p_source / p_call_id say what caused the refresh.
drop function if exists public.refresh_house(uuid);
create or replace function public.refresh_house(p_id uuid, p_source text default null, p_call_id text default null)
returns void language plpgsql security definer set search_path = public as $$
declare
  before record;
  after  record;
  col    record;
begin
  if p_id is null then return; end if;
  select color, called_about into before from public.houses where id = p_id;

     last_checked_at, called_about, call_count, last_called_at, updated_at)
  select a.id, a.address, a.zone_id,
         coalesce(s.status, 'unknown'), s.source, s.note, s.recorded_at,
         coalesce(c.n, 0) > 0, coalesce(c.n, 0), c.last_at, now()
  from public.addresses a
  left join lateral (
    select status, source, note, recorded_at from public.status_log
    where address_id = a.id order by recorded_at desc limit 1
  ) s on true
  left join lateral (
    select count(*)::int as n, max(created_at) as last_at from public.calls where address_id = a.id
  ) c on true
  where a.id = p_id
  on conflict (id) do update set
    address = excluded.address, zone_id = excluded.zone_id,
    evacuation_status = excluded.evacuation_status, evacuation_status_source = excluded.evacuation_status_source,
    evacuation_note = excluded.evacuation_note, last_checked_at = excluded.last_checked_at,
    called_about = excluded.called_about, call_count = excluded.call_count, last_called_at = excluded.last_called_at,
    updated_at = now();

  select h.id, h.address, h.evacuation_status, h.last_checked_at, h.called_about into after from public.houses h where h.id = p_id;
  if after.id is null then return; end if;
  select * into col from public.house_color(after.evacuation_status, after.last_checked_at, p_id);

  update public.houses set color = col.color, color_reason = col.reason,
    color_changed_at = case when color is distinct from col.color then now() else color_changed_at end
  where id = p_id;

  if p_source = 'call' and (before.color is distinct from col.color or (coalesce(before.called_about, false) = false and after.called_about)) then
    values (p_id, after.address, col.color, before.color,
            coalesce(before.called_about, false) = false and after.called_about, col.reason, p_call_id);
  end if;
end $$;

-- status_log: a row written by a call (source 'call') is a Retell event; officer taps aren't.
create or replace function public.houses_from_status() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op in ('INSERT', 'UPDATE') then
    perform public.refresh_house(new.address_id, case when new.source = 'call' then 'call' end, null);
  end if;
  if tg_op = 'DELETE' or (tg_op = 'UPDATE' and old.address_id is distinct from new.address_id) then
    perform public.refresh_house(old.address_id);
  end if;
  return null;
end $$;

-- calls: linking a house, or a routing/bypass change, can recolour it.
create or replace function public.houses_from_calls() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op in ('INSERT', 'UPDATE') then perform public.refresh_house(new.address_id, 'call', new.call_id); end if;
  if tg_op = 'DELETE' or (tg_op = 'UPDATE' and old.address_id is distinct from new.address_id) then
    perform public.refresh_house(old.address_id);
  end if;
  return null;
end $$;

drop trigger if exists houses_calls on public.calls;
create trigger houses_calls after insert or update of address_id, routing, bypass or delete on public.calls
  for each row execute function public.houses_from_calls();

-- Colour every house now (no events: p_source is null).
select public.refresh_house(id) from public.addresses;

-- Time passing: a green house whose clear is now older than 120 minutes turns grey. Only
-- greens can expire (red and yellow don't depend on the clock), so only those are refreshed.
-- Returns how many houses it recoloured.
create or replace function public.expire_house_colors() returns int
language plpgsql security definer set search_path = public as $$
declare
  r record;
  n int := 0;
begin
  for r in select id from public.houses
           where color = 'green' and (last_checked_at is null or last_checked_at < now() - interval '120 minutes')
  loop
    perform public.refresh_house(r.id);
    n := n + 1;
  end loop;
  return n;
end $$;

-- Run it every minute with pg_cron. If the extension isn't enabled on this project this prints
-- a notice instead of failing: enable it (Dashboard -> Database -> Extensions -> pg_cron) and
-- run this file again. Without it, a green house stays green after its clear goes stale until
-- something else touches the house.
do $$ begin
  create extension if not exists pg_cron;
  perform cron.schedule('expire-house-colors', '* * * * *', 'select public.expire_house_colors()');
exception when others then
  raise notice 'pg_cron not scheduled (%): enable it, then re-run house_colors.sql', sqlerrm;
end $$;

alter table public.house_events enable row level security;
drop policy if exists "signed-in portals can read house events" on public.house_events;
create policy "signed-in portals can read house events"
  on public.house_events for select to authenticated using (true);
do $$ begin
  alter publication supabase_realtime add table public.house_events;
exception when duplicate_object then null; end $$;

notify pgrst, 'reload schema';
